import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第二十六章","description":"《正易心法》第二十六章——反对正如，甲子乙丑：凡物之气有本有余，余气为阴、本为阳；坤为乾之余气、蒙为屯之余气，故卦序相次皆余气，自然之理。","frontmatter":{"title":"正易心法·第二十六章","description":"《正易心法》第二十六章——反对正如，甲子乙丑：凡物之气有本有余，余气为阴、本为阳；坤为乾之余气、蒙为屯之余气，故卦序相次皆余气，自然之理。","category":"guide","aliases":["正易心法第二十六章","有本有余气序自然","余气"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-26.md","filePath":"yijing/zheng-yi-xin-fa/chapter-26.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-26.md"},x=p({...c,setup(u){const i=[{id:"z26-01",label:"一、反对正如甲子乙丑",showLabel:!0,sentences:[["反对正如，甲子乙丑。有本有余，",{text:"气序自然",glossary:"qixuZiran"},"。"]],note:["反卦与对卦的关系正是如此——就像甲子与乙丑。有本气，有余气，气的顺序是自然形成的。（**本章是第十六至十八章「反对」体系的更深一层**：前面说「反卦相邻」（结构），本章说「为什么相邻」——**因为后卦是前卦的余气**（气化）。）"]},{id:"z26-02",label:"二、本与余",showLabel:!0,sentences:[["大凡一物，其气象必有本有余。",{text:"余气",glossary:"yuqi"},"者，所以为阴也。本，其阳也。"]],note:["大体上，任何事物的气象必然有本气、有余气。余气，就是阴的来源；本气，就是阳。（**这是本章的框架**：**本＝阳＝充盛、先行**；**余＝阴＝余韵、后随**。这不是经验观察，而是「气」的运行方式：气运行到极处必然收敛，收敛处就是余气。）"]},{id:"z26-03",label:"三、十干之例",showLabel:!0,sentences:[["如",{text:"十干",glossary:"shigan"},"甲乙，乙者甲之余气也。丙丁，丁者丙之余气也。"]],note:["比如十天干中的甲乙：乙，是甲的余气；丙丁：丁，是丙的余气。（**规律很整齐**：甲丙戊庚壬这五个奇数干为「本」（阳），乙丁己辛癸这五个偶数干为「余」（阴）——**每一对都是「阳干＋它的余气」**。）"]},{id:"z26-04",label:"四、十二支之例",showLabel:!0,sentences:[["如",{text:"十二支",glossary:"shierZhi"},"子丑，丑者子之余气也。寅卯，卯者寅之余气也。"]],note:["比如十二地支中的子丑：丑，是子的余气；寅卯：卯，是寅的余气。（**地支的十二个，同样是「阳支为本、阴支为余」交替**。麻衣举天干、地支两例，是在说明「本余」不是卦序特有的规则，而是贯穿一切「气」的编号方式。）"]},{id:"z26-05",label:"五、卦之例",showLabel:!0,sentences:[["卦亦由是。坤者，乾之余气也。蒙者，屯之余气也。讼者，需之余气也。比者，师之余气也。"]],note:["卦的道理也是如此：坤，是乾的余气；蒙，是屯的余气；讼，是需的余气；比，是师的余气。（**对照卦序**：乾（一）→坤（二）、屯（三）→蒙（四）、需（五）→讼（六）、师（七）→比（八）——**每一对都是「奇数卦为本，偶数卦为余」**，而每一对恰好又是互为反卦的（屯与蒙颠倒、需与讼颠倒、师与比颠倒）。**所以「反卦相邻」与「本余相随」是同一件事。**）"]},{id:"z26-06",label:"六、相次皆余气",showLabel:!0,sentences:[["且乾而后坤，屯而后蒙，需而后讼，师而后比，虽故有其义，然其所以",{text:"相次",glossary:"xiangci"},"者，皆其余气也，自然之理耳。"]],note:["乾之后是坤、屯之后是蒙、需之后是讼、师之后是比——虽然这些相邻的卦之间本来就有各自的义理，但它们之所以紧邻排列，都是因为余气的关系，这是自然之理。（**麻衣的分寸**：他并不否定《序卦传》讲的义理，只说「**虽故有其义，然其所以相次者，皆其余气也**」——义理是「有」，余气是「所以然」。**义理说的是「它们有什么关系」，余气说的是「它们为什么挨着」。**）"]},{id:"z26-07",label:"七、学者不悟",showLabel:!0,sentences:[["学者不悟，谓圣人",{text:"固以次之",glossary:"guyiCizhi"},"，是未知",{text:"反对关键之键",glossary:"fanduiGuajian"},"也，失之远矣。"]],note:["学者不能领悟，以为是圣人本来就这样排列的，这是不知道反对关键的关键所在，偏差太远了。（**「固以次之」与「气序自然」正好相反**：一个说「圣人安排的」，一个说「气自己走的」。**「失之远矣」是麻衣极重的批评用语**——不是「理解不深」，是「方向完全错了」。）"]}],l=[{id:"qixuZiran",term:"气序自然",pinyin:"qì xù zì rán",meaning:"气的顺序是自然形成的。卦序不是圣人人为安排，而是气的自然流行。"},{id:"yuqi",term:"余气",pinyin:"yú qì",meaning:"本气散尽后残留的气。阴为阳之余气；偶数干支为奇数干支的余气。"},{id:"shigan",term:"十干",pinyin:"shí gān",meaning:"十天干：甲乙丙丁戊己庚辛壬癸。奇数干为阳（本），偶数干为阴（余）。"},{id:"shierZhi",term:"十二支",pinyin:"shí èr zhī",meaning:"十二地支：子丑寅卯辰巳午未申酉戌亥。奇数支为阳（本），偶数支为阴（余）。"},{id:"xiangci",term:"相次",pinyin:"xiāng cì",meaning:"相互紧邻排列。次是次序，紧接着。"},{id:"guyiCizhi",term:"固以次之",pinyin:"gù yǐ cì zhī",meaning:"本来就是这样排列的。固是本来、原本。"},{id:"fanduiGuajian",term:"反对关键之键",pinyin:"fǎn duì guān jiàn",meaning:"反对义的关键所在。麻衣强调这是理解卦序的核心钥匙。「键」字两见，极言其要。"}];return(b,n)=>{const o=s("DaoTextReading"),r=s("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t("",21)),e(o,{colophon:"有本有余 · 气序自然 · 十干十二支 · 反对关键之键",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十六章原文",sections:i,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"本与余",pinyin:["běn","yú"],meaning:"本＝阳＝充盛、先行；余＝阴＝余韵、后随。凡物之气必有本有余。"},{term:"余气",pinyin:["yú","qì"],meaning:"不是「残渣」，而是「延续」：甲气未散尽则延续为乙，乾气未散尽则延续为坤。"},{term:"气序自然",pinyin:["qì","xù"],meaning:"卦序不是圣人人为安排，而是本余之气的自然流行——反卦相邻即本余相随。"},{term:"固以次之",pinyin:["gù","yǐ"],meaning:"「以为圣人本来就是这样排列的」——麻衣批评学者不悟气序自然之理。"},{term:"反对关键之键",pinyin:["fǎn","duì"],meaning:"反对义的关键所在。「键」字两见，极言其要：余气是反对义的根源。"}]}),n[3]||(n[3]=t("",27))])}}});export{m as __pageData,x as default};
